import type { WaselUser } from '../contexts/LocalAuth';
import { getAuthCallbackUrl, resolveAuthRedirectOrigin } from '../utils/env';
import { supabase } from '../utils/supabase/client';
import { requestEdgeJson, runBackendWorkflow } from './backendWorkflow';
import {
  enableDirectTrustDriverMode,
  submitDirectTrustDriverDocuments,
} from './directSupabase';
import { buildFallbackTrustCenterStatus, type ReviewHistoryItem, type TrustCenterStatus } from './trustCenterModel';

function toErrorMessage ( error: unknown ): string {
  if ( error instanceof Error ) { return error.message; }
  return 'Trust Center request failed.';
}

async function getTrustUserId (): Promise<string> {
  if ( !supabase ) {
    throw new Error( 'Supabase client is not initialised' );
  }

  let session;
  try {
    const result = await supabase.auth.getSession();
    session = result.data?.session ?? null;
  } catch {
    throw new Error( 'Unable to verify your session. Please sign in again.' );
  }

  if ( !session?.user?.id ) {
    throw new Error( 'Not authenticated' );
  }
  return session.user.id;
}

export interface StartPhoneVerificationPayload {
  phoneNumber: string;
}

export interface ConfirmPhoneVerificationPayload {
  code: string;
}

export interface DriverDocumentsPayload {
  licenseNumber: string;
  documentReference?: string;
}

export async function getTrustCenterStatus ( user?: WaselUser | null ): Promise<TrustCenterStatus> {
  if ( !supabase ) {
    if ( user ) { return buildFallbackTrustCenterStatus( user ); }
    throw new Error( 'Supabase client is not initialised' );
  }

  let session;
  try {
    const result = await supabase.auth.getSession();
    session = result.data?.session ?? null;
  } catch {
    if ( user ) { return buildFallbackTrustCenterStatus( user ); }
    throw new Error( 'Unable to verify your session. Please sign in again.' );
  }

  if ( !session ) {
    if ( user ) { return buildFallbackTrustCenterStatus( user ); }
    throw new Error( 'Not authenticated' );
  }

  try {
    const payload = await requestEdgeJson<{ status: TrustCenterStatus }>( {
      path: '/v1/trust/status',
      authMode: 'required',
      operation: 'Trust Center status',
    } );
    return payload.status;
  } catch ( error ) {
    if ( user ) {
      return buildFallbackTrustCenterStatus( user );
    }
    throw new Error( toErrorMessage( error ), { cause: error } );
  }
}

export async function fetchReviewHistory (): Promise<ReviewHistoryItem[]> {
  if ( !supabase ) {
    return [];
  }

  let session;
  try {
    const result = await supabase.auth.getSession();
    session = result.data?.session ?? null;
  } catch {
    return [];
  }

  if ( !session ) {
    return [];
  }

  try {
    const payload = await requestEdgeJson<{ items: ReviewHistoryItem[] }>( {
      path: '/v1/trust/review-history',
      authMode: 'required',
      operation: 'Trust Center review history',
    } );
    return payload.items ?? [];
  } catch {
    return [];
  }
}

export async function startTrustPhoneVerification ( payload: StartPhoneVerificationPayload ) {
  const response = await runBackendWorkflow<{
    started: boolean;
    phoneNumber: string;
    expiresAt: string;
    devCode?: string;
    provider?: string;
  }>( {
    operation: 'Phone verification start',
    authMode: 'required',
    // Phone codes must be sent by the trusted edge function. The direct DB
    // fallback cannot deliver an SMS and must never create a fake OTP session.
    fallbackPolicy: 'never',
    operationType: 'write',
    edge: context =>
      requestEdgeJson( {
        path: '/v1/trust/phone/start',
        method: 'POST',
        body: payload,
        authMode: 'required',
        context,
        operation: 'Phone verification start',
      } ),
  } );

  return response;
}

export async function confirmTrustPhoneVerification ( payload: ConfirmPhoneVerificationPayload ) {
  const response = await runBackendWorkflow<{
    verified: boolean;
    phoneNumber: string;
  }>( {
    operation: 'Phone verification confirmation',
    authMode: 'required',
    // Verification must be checked by the provider or trusted edge service.
    fallbackPolicy: 'never',
    operationType: 'write',
    edge: context =>
      requestEdgeJson( {
        path: '/v1/trust/phone/confirm',
        method: 'POST',
        body: payload,
        authMode: 'required',
        context,
        operation: 'Phone verification confirmation',
      } ),
  } );

  return response;
}

export async function enableTrustDriverMode () {
  const response = await runBackendWorkflow<{
    enabled: boolean;
    role: 'driver';
  }>( {
    operation: 'Driver mode enablement',
    authMode: 'required',
    fallbackPolicy: 'always',
    operationType: 'write',
    edge: context =>
      requestEdgeJson( {
        path: '/v1/trust/driver-mode/enable',
        method: 'POST',
        authMode: 'required',
        context,
        operation: 'Driver mode enablement',
      } ),
    fallback: async context => {
      const userId = context.userId ?? ( await getTrustUserId() );
      return enableDirectTrustDriverMode( userId );
    },
  } );

  return response;
}

export async function submitTrustDriverDocuments ( payload: DriverDocumentsPayload ) {
  const response = await runBackendWorkflow<{
    submitted: boolean;
    driverId: string;
  }>( {
    operation: 'Driver documents submission',
    authMode: 'required',
    fallbackPolicy: 'always',
    operationType: 'write',
    edge: context =>
      requestEdgeJson( {
        path: '/v1/trust/driver-documents/submit',
        method: 'POST',
        body: payload,
        authMode: 'required',
        context,
        operation: 'Driver documents submission',
      } ),
    fallback: context => submitDirectTrustDriverDocuments( context.userId ?? '', payload ),
  } );

  return response;
}

export async function resendTrustEmailConfirmation ( email: string ) {
  if ( !supabase ) {
    throw new Error( 'Supabase auth is not configured for email confirmation.' );
  }

  const { error } = await supabase.auth.resend( {
    type: 'signup',
    email,
    options: {
      emailRedirectTo: getAuthCallbackUrl( resolveAuthRedirectOrigin() ),
    },
  } );

  if ( error ) {
    throw error;
  }
}
